/* Match the handoff's #0B0B0B -> #E0F1F0 grayscale in the panel's wire order. */
uint16_t board_mist_gray_color(uint8_t value)
{
    const unsigned r = 11 + (213U * value + 127U) / 255U;
    const unsigned g = 11 + (230U * value + 127U) / 255U;
    const unsigned b = 11 + (229U * value + 127U) / 255U;
    const uint16_t rgb = (((r * 31U + 127U) / 255U) << 11) |
                         (((g * 63U + 127U) / 255U) << 5) |
                         ((b * 31U + 127U) / 255U);
    return (uint16_t)((rgb << 8) | (rgb >> 8));
}

void board_mist_draw_icon(uint16_t *strip, int width, int height,
                          int strip_y, int strip_lines, board_mist_icon_t icon,
                          int center_x, int center_y, uint8_t pitch,
                          uint8_t brightness)
{
    const board_mist_icon_asset_t *asset = board_mist_icon_asset(icon);
    if (strip == NULL || asset == NULL || pitch < 2 || pitch > 4) {
        return;
    }
    const int cell = pitch - 1;
    const int left = center_x - (asset->width * pitch - 1) / 2;
    const int top = center_y - (asset->height * pitch - 1) / 2;
    for (unsigned row = 0; row < asset->height; ++row) {
        const int y = top + row * pitch;
        if (y >= strip_y + strip_lines || y + cell <= strip_y) {
            continue;
        }
        for (unsigned column = 0; column < asset->width; ++column) {
            if (!(asset->rows[row] & (1U << (asset->width - 1 - column)))) {
                continue;
            }
            const int x = left + column * pitch;
            if (x < 0 || y < 0 || x + cell > width || y + cell > height ||
                !board_display_circular_aperture_contains(x, y, width, height, 125) ||
                !board_display_circular_aperture_contains(x + cell - 1, y, width, height, 125) ||
                !board_display_circular_aperture_contains(x, y + cell - 1, width, height, 125) ||
                !board_display_circular_aperture_contains(x + cell - 1, y + cell - 1, width, height, 125)) {
                continue;
            }
            const unsigned level = asset->levels
                ? asset->levels[row * asset->width + column] : 255u;
            const uint16_t color = board_mist_gray_color(
                (level * brightness + 127U) / 255U);
            for (int dy = 0; dy < cell; ++dy) {
                if (y + dy < strip_y || y + dy >= strip_y + strip_lines) {
                    continue;
                }
                for (int dx = 0; dx < cell; ++dx) {
                    strip[(y + dy - strip_y) * width + x + dx] = color;
                }
            }
        }
    }
}
